fn helper(path: Text) -> Int uses fs or fail {
    let body = try read_file(path)
    return length(body)
}

fn wrapper(path: Text) -> Int uses fs or fail {
    return try helper(path)
}

fn main() uses io, fs {
    check wrapper("{DATA}/a.txt") {
        ok n {
            print("GOT THROUGH")
        }
        fail why {
            print("failed")
        }
    }
}
